def minmax_normalize_within_query(
    frame: pd.DataFrame,
    score_column: str,
    output_column: str,
) -> pd.DataFrame:

    output = frame.copy()

    normalized_parts = []

    for _, group in output.groupby(
        "query_id",
        sort=False,
    ):

        scores = group[
            score_column
        ].to_numpy(
            dtype=np.float64
        )

        minimum = float(
            np.min(scores)
        )

        maximum = float(
            np.max(scores)
        )

        if maximum > minimum:

            normalized = (
                scores - minimum
            ) / (
                maximum - minimum
            )

        else:

            normalized = np.zeros_like(
                scores
            )

        normalized_parts.append(
            pd.Series(
                normalized,
                index=group.index,
                dtype=np.float64,
            )
        )

    output[
        output_column
    ] = pd.concat(
        normalized_parts
    ).sort_index()

    return output

